import userEvent from '@testing-library/user-event';
import { Field } from '@base-ui/react/field';
import { Input } from '@base-ui/react/input';
import { Combobox } from '@base-ui/react/combobox';

type Country = { id: string; label: string };
const items: Country[] = [
  { id: 'fr', label: 'France' },
  { id: 'de', label: 'Germany' },
];

function rootSnap() {
  const root = screen.getByTestId('root');
  const error = screen.queryByTestId('error');
  return {
    dirty: root.hasAttribute('data-dirty'),
    filled: root.hasAttribute('data-filled'),
    invalid: root.hasAttribute('data-invalid'),
    valid: root.hasAttribute('data-valid'),
    error: error ? error.textContent : null,
    inputValue: (screen.getByTestId('input') as HTMLInputElement).value,
  };
}

function App(props: { validate: (v: unknown) => string | null; defaultValue?: Country; plain?: boolean }) {
  return (
    <Field.Root name="country" data-testid="root" validationMode="onChange" validate={props.validate}>
      <Combobox.Root items={items} defaultValue={props.defaultValue}>
        {props.plain ? (
          <Combobox.Input data-testid="input" />
        ) : (
          <Combobox.Input render={<Input data-testid="input" />} />
        )}
        <Combobox.Portal>
          <Combobox.Positioner>
            <Combobox.Popup>
              <Combobox.List>
                {(item: Country) => (
                  <Combobox.Item key={item.id} value={item}>
                    {item.label}
                  </Combobox.Item>
                )}
              </Combobox.List>
            </Combobox.Popup>
          </Combobox.Positioner>
        </Combobox.Portal>
      </Combobox.Root>
      <Field.Error data-testid="error" />
    </Field.Root>
  );
}

export function defineCombo2Scenarios(label: string) {
  const log = (name: string, obs: unknown) =>
    appendFileSync('$S/obs-combo2.log', \`OBS[\${label}] \${name}: \${JSON.stringify(obs)}\\n\`);
  const makeValidate = () =>
    vi.fn((v: unknown) => (v == null || typeof v === 'object' ? null : 'Pick a country from the list'));

  it('C4 typing a filter query into composed Input (no selection yet)', async () => {
    const validate = makeValidate();
    const user = userEvent.setup();
    render(<App validate={validate} />);
    await user.type(screen.getByTestId('input'), 'Fr');
    await act(async () => {});
    log('C4', { ...rootSnap(), validateCalls: validate.mock.calls.map((c) => c[0]) });
    cleanup();
  });

  it('C4p same with plain Combobox.Input (control)', async () => {
    const validate = makeValidate();
    const user = userEvent.setup();
    render(<App validate={validate} plain />);
    await user.type(screen.getByTestId('input'), 'Fr');
    await act(async () => {});
    log('C4p', { ...rootSnap(), validateCalls: validate.mock.calls.map((c) => c[0]) });
    cleanup();
  });

  it('C5 valid default selection, then typing a filter query', async () => {
    const validate = makeValidate();
    const user = userEvent.setup();
    render(<App validate={validate} defaultValue={items[0]} />);
    const before = rootSnap();
    await user.type(screen.getByTestId('input'), 'x');
    await act(async () => {});
    log('C5', { before, after: rootSnap(), validateCalls: validate.mock.calls.map((c) => c[0]) });
    cleanup();
  });

  it('C6 validator dereferences object fields; typing', async () => {
    const validate = vi.fn((v: unknown) => ((v as Country | null)?.id.startsWith('f') ? null : 'Must start with f'));
    const user = userEvent.setup();
    let thrown: string | null = null;
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    try {
      render(<App validate={validate} defaultValue={items[0]} />);
      await user.type(screen.getByTestId('input'), 'x');
      await act(async () => {});
    } catch (error) {
      thrown = String(error);
    }
    log('C6', { thrown, stillMounted: !!screen.queryByTestId('root'), validateCalls: validate.mock.calls.map((c) => c[0]) });
    spy.mockRestore();
    cleanup();
  });
}
