const variant = process.env.FC_BASE === '1' ? 'BASE' : 'HEAD';

function report(name: string, data: unknown) {
  appendFileSync(
    `${__dirname}/results3-${variant}.txt`,
    `RESULT[${variant}] ${name}: ${JSON.stringify(data)}\n`,
  );
}

