describe('probe3', () => {
  it('11. NumberField with field-aware Input', () => {
    const seen: unknown[] = [];
    function validate(value: unknown) {
      seen.push(value);
      return typeof value === 'number' && value > 1000 ? 'Too big' : null;
    }
    function App() {
      const [value, setValue] = React.useState<number | null>(5);
      return (
        <Field.Root name="amount" data-testid="root" validationMode="onChange" validate={validate}>
          <NumberField.Root value={value} onValueChange={setValue}>
            <NumberField.Group>
              <NumberField.Decrement>-</NumberField.Decrement>
              <NumberField.Input render={<Input data-testid="input" />} />
              <NumberField.Increment data-testid="inc">+</NumberField.Increment>
            </NumberField.Group>
          </NumberField.Root>
          <Field.Error data-testid="error" />
          <button type="button" onClick={() => setValue(2000)}>
            set 2000
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    fireEvent.click(screen.getByText('set 2000'));
    report('numberfield programmatic 2000', {
      validateArgs: seen.slice(),
      inputValue: (screen.getByTestId('input') as HTMLInputElement).value,
      error: screen.queryByTestId('error')?.textContent ?? null,
      rootInvalid: root.hasAttribute('data-invalid'),
      dirty: root.hasAttribute('data-dirty'),
    });
  });
});
